/**
 * WeaponEventTypes - Central registry for weapon event type constants
 *
 * Provides typed constants for all weapon events. Using these constants
 * instead of hardcoded strings enables IDE autocompletion, prevents typos,
 * and makes event types discoverable.
 *
 * @module @three-blocks/pro/core/WeaponEventTypes
 * @short Central weapon event type registry
 * @category Physics
 * @tags Events, Constants, Weapons
 *
 * @example
 * ```js
 * import { WeaponEvent } from '@three-blocks/pro';
 *
 * weapon.addEventListener(WeaponEvent.EXPLODE, (event) => {
 *   console.log('Explosion at:', event.position);
 * });
 * ```
 */
/**
 * Emitted when weapon is fired.
 * @type {string}
 * @event fire
 * @property {number} weaponIndex - Index of the weapon that fired
 * @property {Object} origin - Fire origin { x, y, z }
 * @property {Object} direction - Fire direction { x, y, z }
 */
export const FIRE: string;
/**
 * Emitted when projectile or hitscan ray hits a target.
 * @type {string}
 * @event hit
 * @property {number} shooterIndex - Index of the shooter body
 * @property {string} shooterType - Type of the shooter body
 * @property {number} targetIndex - Index of the hit body
 * @property {string} targetType - Type of the hit body
 * @property {Object} hitPoint - Hit point { x, y, z }
 * @property {Object} hitNormal - Surface normal at hit point { x, y, z }
 * @property {number} distance - Distance from shooter to hit
 * @property {number} damage - Damage dealt
 * @property {string} weaponType - 'hitscan', 'projectile', or 'hybrid'
 * @property {number} [projectileId] - Projectile index (projectiles only)
 * @property {number} [flightTime] - Flight time in seconds (projectiles only)
 */
export const HIT: string;
/**
 * Emitted when projectile explodes (on collision or timeout).
 * @type {string}
 * @event explode
 * @property {number} projectileId - Projectile index in physics simulation
 * @property {Object} position - Explosion location { x, y, z }
 * @property {Object} velocity - Projectile velocity at detonation { x, y, z }
 * @property {number} damage - Base damage value
 * @property {number} aoeRadius - Blast radius in meters
 * @property {number} shooterIndex - Index of the shooter body
 * @property {string} shooterType - Type of the shooter body ('dynamic' or 'kinematic')
 * @property {'collision'|'timeout'} cause - What triggered the explosion
 * @property {string} [targetType] - Type of hit body (only if cause === 'collision')
 * @property {number} [targetIndex] - Index of hit body (only if cause === 'collision')
 * @property {number} timestamp - Physics frame time of explosion
 */
export const EXPLODE: string;
/**
 * Emitted when projectile is spawned (for custom visual effects).
 * @type {string}
 * @event spawn
 * @property {number} projectileId - Projectile index
 * @property {Object} position - Spawn position { x, y, z }
 * @property {Object} velocity - Initial velocity { x, y, z }
 */
export const SPAWN: string;
/**
 * Emitted when projectile is deactivated (lifetime expired or hit).
 * @type {string}
 * @event despawn
 * @property {number} projectileId - Projectile index that despawned
 */
export const DESPAWN: string;
export namespace WeaponEvent {
    export { FIRE };
    export { HIT };
    export { EXPLODE };
    export { SPAWN };
    export { DESPAWN };
}
